Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "dataset"
  },
  "width": 322,
  "height": 254,
  "padding": 0,
  "autosize": {
    "type": "none"
  },
  "background": "transparent",
  "config": {
    "view": {
      "stroke": null
    }
  },
  "transform": [
    {
      "fold": [
        "Avg Risk Weighting",
        "Avg Products Held"
      ],
      "as": [
        "key",
        "value"
      ]
    },
    {
      "calculate": "datum.key == ''Avg Risk Weighting'' ? ''Risk'' : ''Products''",
      "as": "m"
    },
    {
      "calculate": "datum.m == ''Risk'' ? 5 : 6",
      "as": "hi"
    },
    {
      "calculate": "clamp((datum.value - 1) / (datum.hi - 1), 0, 1)",
      "as": "frac"
    },
    {
      "calculate": "format(datum.value, ''.2f'')",
      "as": "label"
    },
    {
      "calculate": "datum.m == ''Risk'' ? ''avg risk level, scale 1 to 5'' : ''avg products held, scale 1 to 6''",
      "as": "caption"
    },
    {
      "calculate": "datum.m == ''Risk'' ? 188 : 232",
      "as": "px1"
    },
    {
      "calculate": "datum.m == ''Risk'' ? 230 : 301",
      "as": "px2"
    },
    {
      "calculate": "(datum.px1 + datum.px2) / 2",
      "as": "pcx"
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 13,
        "fill": "#C9A45C"
      },
      "encoding": {
        "x": {
          "field": "px1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "px2"
        },
        "y": {
          "value": 6
        },
        "y2": {
          "value": 32
        }
      }
    },
    {
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        }
      ],
      "mark": {
        "type": "text",
        "font": "Plus Jakarta Sans",
        "fontSize": 10.5,
        "fontWeight": 700,
        "fill": "#17140F",
        "align": "center",
        "baseline": "middle"
      },
      "encoding": {
        "x": {
          "field": "pcx",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "value": 19.5
        },
        "text": {
          "field": "m",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": {
            "not": {
              "param": "metric"
            }
          }
        }
      ],
      "mark": {
        "type": "text",
        "font": "Plus Jakarta Sans",
        "fontSize": 10.5,
        "fontWeight": 400,
        "fill": "#2F2B26",
        "align": "center",
        "baseline": "middle"
      },
      "encoding": {
        "x": {
          "field": "pcx",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "value": 19.5
        },
        "text": {
          "field": "m",
          "type": "nominal"
        }
      }
    },
    {
      "params": [
        {
          "name": "metric",
          "value": [
            {
              "m": "Risk"
            }
          ],
          "select": {
            "type": "point",
            "fields": [
              "m"
            ],
            "on": "click",
            "toggle": false,
            "clear": false
          }
        }
      ],
      "mark": {
        "type": "rect",
        "fill": "#FFFFFF",
        "opacity": 0,
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "px1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "px2"
        },
        "y": {
          "value": 6
        },
        "y2": {
          "value": 32
        }
      }
    },
    {
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        },
        {
          "calculate": "sequence(0, 36)",
          "as": "i"
        },
        {
          "flatten": [
            "i"
          ]
        },
        {
          "calculate": "(-120 + 240 * datum.i / 35) * PI / 180",
          "as": "a"
        },
        {
          "calculate": "159.5 + 73 * sin(datum.a)",
          "as": "x1"
        },
        {
          "calculate": "164 - 73 * cos(datum.a)",
          "as": "y1"
        },
        {
          "calculate": "159.5 + 94 * sin(datum.a)",
          "as": "x2"
        },
        {
          "calculate": "164 - 94 * cos(datum.a)",
          "as": "y2"
        },
        {
          "calculate": "datum.i % 2 == 0 ? ''#D9BC7E'' : ''#E8D6AE''",
          "as": "c"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": 7,
        "strokeCap": "round"
      },
      "encoding": {
        "x": {
          "field": "x1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "field": "y1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "x2"
        },
        "y2": {
          "field": "y2"
        },
        "color": {
          "field": "c",
          "type": "nominal",
          "scale": null,
          "legend": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        },
        {
          "calculate": "sequence(0, 30)",
          "as": "i"
        },
        {
          "flatten": [
            "i"
          ]
        },
        {
          "calculate": "(-120 + 240 * datum.i / 29) * PI / 180",
          "as": "a"
        },
        {
          "calculate": "159.5 + 51 * sin(datum.a)",
          "as": "x1"
        },
        {
          "calculate": "164 - 51 * cos(datum.a)",
          "as": "y1"
        },
        {
          "calculate": "159.5 + 65 * sin(datum.a)",
          "as": "x2"
        },
        {
          "calculate": "164 - 65 * cos(datum.a)",
          "as": "y2"
        },
        {
          "calculate": "datum.i / 29 <= datum.frac ? ''#17140F'' : ''#E4DFD5''",
          "as": "c"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": 4.5,
        "strokeCap": "round"
      },
      "encoding": {
        "x": {
          "field": "x1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "y": {
          "field": "y1",
          "type": "quantitative",
          "scale": null,
          "axis": null
        },
        "x2": {
          "field": "x2"
        },
        "y2": {
          "field": "y2"
        },
        "color": {
          "field": "c",
          "type": "nominal",
          "scale": null,
          "legend": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "x": 159.5,
        "y": 175,
        "fontSize": 36,
        "fontWeight": 700,
        "fill": "#17140F",
        "align": "center",
        "baseline": "alphabetic",
        "font": "Plus Jakarta Sans"
      },
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        }
      ],
      "encoding": {
        "text": {
          "field": "label",
          "type": "nominal"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "x": 159.5,
        "y": 197,
        "fontSize": 10.5,
        "fontWeight": 400,
        "fill": "#6B665D",
        "align": "center",
        "baseline": "alphabetic",
        "font": "Plus Jakarta Sans"
      },
      "transform": [
        {
          "filter": {
            "param": "metric"
          }
        }
      ],
      "encoding": {
        "text": {
          "field": "caption",
          "type": "nominal"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "x": 23,
        "y": 50,
        "size": 45,
        "fill": "#17140F",
        "opacity": 1
      }
    },
    {
      "mark": {
        "type": "text",
        "x": 32,
        "y": 54,
        "fontSize": 10.5,
        "fontWeight": 400,
        "fill": "#6B665D",
        "align": "left",
        "baseline": "alphabetic",
        "font": "Plus Jakarta Sans",
        "text": "Average level"
      }
    },
    {
      "mark": {
        "type": "circle",
        "x": 115,
        "y": 50,
        "size": 45,
        "fill": "#D9BC7E",
        "opacity": 1
      }
    },
    {
      "mark": {
        "type": "text",
        "x": 125,
        "y": 54,
        "fontSize": 10.5,
        "fontWeight": 400,
        "fill": "#6B665D",
        "align": "left",
        "baseline": "alphabetic",
        "font": "Plus Jakarta Sans",
        "text": "Full scale"
      }
    }
  ]
}'
